    runs = []
    r = 0
    while r < h:
        if any(v != bg for v in grid[r]):
            start = r
            while r < h and any(v != bg for v in grid[r]):
                r += 1
            runs.append((start, r))
        else:
            r += 1

    best = None
    for i, (a0, a1) in enumerate(runs):
        for b0, b1 in runs[i + 1:]:
            if a1 - a0 != b1 - b0:
                continue
            n = a1 - a0
            for dx in range(-w // 4, w // 4 + 1):
                eq = miss_b = miss_a = conflicts = overlap = 0
                for k in range(n):
                    for c in range(w):
                        j = c - dx
                        if not 0 <= j < w:
                            continue
                        x, y = grid[a0 + k][j], grid[b0 + k][c]
                        overlap += 1
                        if x == y:
                            eq += 1
                        elif x != bg and y == bg:
                            miss_b += 1
                        elif x == bg and y != bg:
                            miss_a += 1
                        else:
                            conflicts += 1
                if overlap < n * w * 0.75 or eq == 0:
                    continue
                key = (eq / overlap, eq, overlap, -(miss_b + miss_a + conflicts))
                if best is None or key > best[0]:
                    best = (key, a0, b0, n, dx, miss_b, miss_a, conflicts)

    if best is None:
        return out
    _, a0, b0, n, dx, miss_b, miss_a, conflicts = best
    if conflicts or (miss_b and miss_a):
        return out
    for k in range(n):
